(2101303, 287980, 15711, '<td valign="top">Nicely done.  I like the light.  The black and white works with her striking dark hair and eyes for excellent contrast. The jewel in her nose adds that bit of sparkle which sets it off.  8</td>', 'Nicely done.  I like the light.  The black and white works with her striking dark hair and eyes for excellent contrast. The jewel in her nose adds that bit of sparkle which sets it off.  8', '2006-01-30 08:37:32.000000', NULL, 1),
(2101304, 287733, 15711, '<td valign="top">I like this very much.  The single bison against the dry rough wintery scene is great. I like the slight grain - goes along with the sense of a wilderness setting.  The sky is wonderful. 9</td>', 'I like this very much.  The single bison against the dry rough wintery scene is great. I like the slight grain - goes along with the sense of a wilderness setting.  The sky is wonderful. 9', '2006-01-30 08:38:36.000000', NULL, 1),
(2101308, 286169, 15711, '<td valign="top">Excellent. Love the deep rich variations of gray to black. Bumping up on 2nd review.  This is great photojournalism. 9</td>', 'Excellent. Love the deep rich variations of gray to black. Bumping up on 2nd review.  This is great photojournalism. 9', '2006-01-30 08:38:58.000000', NULL, 1),
