(2101346, 286762, 32133, '<td valign="top">This is really beautiful.  It reminds me of my grandfathers photography.  10</td>', 'This is really beautiful.  It reminds me of my grandfathers photography.  10', '2006-01-30 08:49:04.000000', NULL, 1),
(2101348, 287259, 15711, '<td valign="top">Beautiful! We see lots of flower macros and they can get tedious, but this stands out from the crowd.  I don''t realy know why.  Perhaps the subtle colors. The detail and focus - spot on.  Truly lovely.</td>', 'Beautiful! We see lots of flower macros and they can get tedious, but this stands out from the crowd.  I don''t realy know why.  Perhaps the subtle colors. The detail and focus - spot on.  Truly lovely.', '2006-01-30 08:49:47.000000', NULL, 1),
