(2101366, 287674, 32133, '<td valign="top">Great cat shot!</td>', 'Great cat shot!', '2006-01-30 08:53:23.000000', NULL, 1),
(2101369, 287829, 15711, '<td valign="top">Beautiful. So unusual. The complementary olive/avacado green with the rich purple - wow.  Love the lighting and the use of negative space.  Sometimes those types of frames don''t work, but this really sets off the beautiful emerging blossom.  Outstanding. Bumping up on 2nd review - 9</td>', 'Beautiful. So unusual. The complementary olive/avacado green with the rich purple - wow.  Love the lighting and the use of negative space.  Sometimes those types of frames don''t work, but this really sets off the beautiful emerging blossom.  Outstanding. Bumping up on 2nd review - 9', '2006-01-30 08:53:59.000000', NULL, 1),
