(2101504, 287829, 35545, '<td valign="top">This looks very contrived.</td>', 'This looks very contrived.', '2006-01-30 09:39:20.000000', NULL, 1),
(2101506, 286396, 35545, '<td valign="top">This is too contrived.</td>', 'This is too contrived.', '2006-01-30 09:39:52.000000', NULL, 1),
(2101510, 286036, 35545, '<td valign="top">Need to have some more definition on his beak.  It just blends into the black background.</td>', 'Need to have some more definition on his beak.  It just blends into the black background.', '2006-01-30 09:40:53.000000', NULL, 1),
(2101514, 287005, 35545, '<td valign="top">Good candid.  Good use of b&amp;w.</td>', 'Good candid.  Good use of b&w.', '2006-01-30 09:42:41.000000', NULL, 1),
(2101516, 287785, 35545, '<td valign="top">Hard to pick the subject out of the background.</td>', 'Hard to pick the subject out of the background.', '2006-01-30 09:43:23.000000', NULL, 1),
(2101522, 288071, 35545, '<td valign="top">Nice portrait of the child, but the tilt is too contrived.</td>', 'Nice portrait of the child, but the tilt is too contrived.', '2006-01-30 09:46:46.000000', NULL, 1),
(2101524, 286964, 35545, '<td valign="top">Good idea, but you need better focus.</td>', 'Good idea, but you need better focus.', '2006-01-30 09:47:39.000000', NULL, 1),
(2101525, 286940, 35545, '<td valign="top">I really wish you hadn''t cut the top of his head off.</td>', 'I really wish you hadn''t cut the top of his head off.', '2006-01-30 09:48:20.000000', NULL, 1),
(2101527, 286909, 47704, '<td valign="top">You should have entered this in Blue.  Would have fit perfectly.</td>', 'You should have entered this in Blue.  Would have fit perfectly.', '2006-01-30 09:49:18.000000', NULL, 1),
(2101530, 287148, 35545, '<td valign="top">This looks too awkward.</td>', 'This looks too awkward.', '2006-01-30 09:49:51.000000', NULL, 1),
(2101537, 287769, 35545, '<td valign="top">Good picture, but it needs to be bigger.  It could use some light on the man''s figure -- just enough to give it some more definition.  <br/> <br/>Technically, i guess this is off center, but it doesn''t really give that impression.  The fire is what draws our eye, and it is balanced by the coffee pot and the man''s figure.  The total impression, with the square format, is a centered picture.</td>', 'Good picture, but it needs to be bigger.  It could use some light on the man''s figure -- just enough to give it some more definition.   Technically, i guess this is off center, but it doesn''t really give that impression.  The fire is what draws our eye, and it is balanced by the coffee pot and the man''s figure.  The total impression, with the square format, is a centered picture.', '2006-01-30 09:52:46.000000', NULL, 1),
(2101543, 286456, 35545, '<td valign="top">I like the colors, but the tilt kills it for me.  Also, the white on white in the makes it hard to pick out the hydrant.</td>', 'I like the colors, but the tilt kills it for me.  Also, the white on white in the makes it hard to pick out the hydrant.', '2006-01-30 09:54:42.000000', NULL, 1),
(2101545, 287556, 35545, '<td valign="top">Good capture of the two children, but they need to be sharper.</td>', 'Good capture of the two children, but they need to be sharper.', '2006-01-30 09:55:19.000000', NULL, 1),
(2101549, 286783, 35545, '<td valign="top">I''d have cropped it to get rid of a lot of the white tables which aren''t very interesting.  You''d still have had a good picture with the subjec off-center.</td>', 'I''d have cropped it to get rid of a lot of the white tables which aren''t very interesting.  You''d still have had a good picture with the subjec off-center.', '2006-01-30 09:57:12.000000', NULL, 1),
(2101551, 287601, 35545, '<td valign="top">I''d crop off a lot of the bottom.  You''d still have the bee off-center, and IMHO, the picture would have more impact.</td>', 'I''d crop off a lot of the bottom.  You''d still have the bee off-center, and IMHO, the picture would have more impact.', '2006-01-30 09:59:03.000000', NULL, 1),
(2101558, 287358, 35545, '<td valign="top">I don''t think the vertical orientation helps this picture.  I''d go with a square-ish format.  Good use of monochrome.</td>', 'I don''t think the vertical orientation helps this picture.  I''d go with a square-ish format.  Good use of monochrome.', '2006-01-30 10:00:36.000000', NULL, 1),
(2101570, 285650, 35545, '<td valign="top">I wish you hadn''t cut off the top of his head.  Could use some more light on his face.</td>', 'I wish you hadn''t cut off the top of his head.  Could use some more light on his face.', '2006-01-30 10:02:04.000000', NULL, 1),
(2101573, 285322, 37961, '<td valign="top">Creepy editing job.</td>', 'Creepy editing job.', '2006-01-30 10:03:39.000000', NULL, 1),
(2101574, 286276, 35545, '<td valign="top">Love the color and geometry.</td>', 'Love the color and geometry.', '2006-01-30 10:04:00.000000', NULL, 1),
(2101575, 287645, 35545, '<td valign="top">Need to make the buy and his bike stand out more from the background.  Not sure that this was a good choice for selective de-sat.</td>', 'Need to make the buy and his bike stand out more from the background.  Not sure that this was a good choice for selective de-sat.', '2006-01-30 10:04:44.000000', NULL, 1),
(2101577, 287515, 36606, '<td valign="top">love the B/W conversion on this one</td>', 'love the B/W conversion on this one', '2006-01-30 10:05:07.000000', NULL, 1),
(2101579, 288014, 35545, '<td valign="top">Way too contrived.</td>', 'Way too contrived.', '2006-01-30 10:06:51.000000', NULL, 1),
(2101601, 287933, 49773, '<td valign="top">i love the textures, great photo</td>', 'i love the textures, great photo', '2006-01-30 10:13:33.000000', NULL, 1),
(2101624, 287994, 9073, '<td valign="top">Kudos to the reversed reflected colours! Beautiful.</td>', 'Kudos to the reversed reflected colours! Beautiful.', '2006-01-30 10:27:31.000000', NULL, 1),
(2101627, 286935, 3741, '<td valign="top">Beautiful! Frame-worthy for sure, and I love the border :D</td>', 'Beautiful! Frame-worthy for sure, and I love the border :D', '2006-01-30 10:29:37.000000', NULL, 1),
(2101628, 287975, 3741, '<td valign="top">Love the perspective and the different textures :D</td>', 'Love the perspective and the different textures :D', '2006-01-30 10:31:00.000000', NULL, 1),
(2101632, 287313, 3741, '<td valign="top">So elegant, and I love the play on words :D</td>', 'So elegant, and I love the play on words :D', '2006-01-30 10:32:29.000000', NULL, 1),
(2101636, 287936, 3741, '<td valign="top">Vivid and powerful, one of the best kitty pix I''ve ever seen. How''d you get the sweetie to hold so still? :P</td>', 'Vivid and powerful, one of the best kitty pix I''ve ever seen. How''d you get the sweetie to hold so still? :P', '2006-01-30 10:35:20.000000', NULL, 1),
(2101638, 287999, 3741, '<td valign="top">I love the colour choice, and I''m definitely impressed with the glowing appearance of the flower :D</td>', 'I love the colour choice, and I''m definitely impressed with the glowing appearance of the flower :D', '2006-01-30 10:37:24.000000', NULL, 1),
(2101643, 287926, 3741, '<td valign="top">I don''t know what to say other than I love it :D It makes me want to go fishing :P</td>', 'I don''t know what to say other than I love it :D It makes me want to go fishing :P', '2006-01-30 10:40:06.000000', NULL, 1),
(2101644, 286862, 34134, '<td valign="top">This is really great. Beautiful capture. Love the water color and wings!</td>', 'This is really great. Beautiful capture. Love the water color and wings!', '2006-01-30 10:41:17.000000', NULL, 1),
(2101645, 285969, 31443, '<td valign="top">Didn''t think much of this image at first but now looking at it for the second time I see this RAW or as is feeling about it that is so special..</td>', 'Didn''t think much of this image at first but now looking at it for the second time I see this RAW or as is feeling about it that is so special..', '2006-01-30 10:41:38.000000', NULL, 1),
