(2103863, 287926, 24454, '<td valign="top">Very beautiful.  I just love photos like this.    The silhouette is standing just in the right place to keep the sun from looking too blown out.  Great job.  One of my favorites!</td>', 'Very beautiful.  I just love photos like this.    The silhouette is standing just in the right place to keep the sun from looking too blown out.  Great job.  One of my favorites!', '2006-01-30 22:14:16.000000', NULL, 1),
(2103867, 287025, 10413, '<td valign="top">I''ll be curious to see where this was taken. Black bellied whistleing ducks. I live in North Texas and it''s very rare to see them there but we had some on our private lake last year. The are beautiful ducks. Very nice shot!</td>', 'I''ll be curious to see where this was taken. Black bellied whistleing ducks. I live in North Texas and it''s very rare to see them there but we had some on our private lake last year. The are beautiful ducks. Very nice shot!', '2006-01-30 22:14:59.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2103873, 287994, 10413, '<td valign="top">Excellent shot! I love the colored reflection on the car. Good luck!!!</td>', 'Excellent shot! I love the colored reflection on the car. Good luck!!!', '2006-01-30 22:18:53.000000', NULL, 1),
(2103925, 285974, 7743, '<td valign="top">Nice colours and amazing luck to have included the bird, however I feel the image is out of balance.  The gold area has some nice texture to it however the blue area is too flat and uninteresting to add much to this image.  Cropping most of the blue (not all) so that it is about half the width of the gold I think would make for a much stronger image.</td>', 'Nice colours and amazing luck to have included the bird, however I feel the image is out of balance.  The gold area has some nice texture to it however the blue area is too flat and uninteresting to add much to this image.  Cropping most of the blue (not all) so that it is about half the width of the gold I think would make for a much stronger image.', '2006-01-30 22:38:33.000000', NULL, 1),
(2103965, 287030, 46743, '<td valign="top">Sweet Pic! It''s Jawa Lady. he he.</td>', 'Sweet Pic! It''s Jawa Lady. he he.', '2006-01-30 23:00:46.000000', NULL, 1),
