(2104666, 287259, 51228, '<td valign="top">Good composition but a loss of detail in the shadows. Nice sharp petals but centre a little soft.</td>', 'Good composition but a loss of detail in the shadows. Nice sharp petals but centre a little soft.', '2006-01-31 08:25:22.000000', NULL, 1),
(2104672, 287121, 51228, '<td valign="top">Great idea. Think that centre of rose may have benefitted from being on an intersection of 3rds. Just a bit too high for me. Fade a little too gradual so lost detail on RHS petals.</td>', 'Great idea. Think that centre of rose may have benefitted from being on an intersection of 3rds. Just a bit too high for me. Fade a little too gradual so lost detail on RHS petals.', '2006-01-31 08:28:02.000000', NULL, 1),
(2104677, 287952, 51228, '<td valign="top">What a lovely lad. Dad (or whoever) has just missed out though on showing his real potential by not exposing for his eyes. Super composition. Really grabs you.</td>', 'What a lovely lad. Dad (or whoever) has just missed out though on showing his real potential by not exposing for his eyes. Super composition. Really grabs you.', '2006-01-31 08:31:23.000000', NULL, 1),
