(2105239, 288023, 23251, '<td valign="top">I find the little white dot distracting below the switch at the tip of the reflection.</td>', 'I find the little white dot distracting below the switch at the tip of the reflection.', '2006-01-31 13:09:24.000000', NULL, 1),
(2105240, 287900, 32966, '<td valign="top">Great shot!  He looks poised for action, even if he''s only on one leg atm.</td>', 'Great shot!  He looks poised for action, even if he''s only on one leg atm.', '2006-01-31 13:09:28.000000', NULL, 1),
(2105241, 286318, 27562, '<td valign="top">Very atomspheric &amp; moody. It reminds me of a Edward Hopper painting.  Nice.</td>', 'Very atomspheric & moody. It reminds me of a Edward Hopper painting.  Nice.', '2006-01-31 13:09:48.000000', NULL, 1),
