INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2106260, 287923, 35786, '<td valign="top">the technicals of this photo are very good but not a real strong setup...</td>', 'the technicals of this photo are very good but not a real strong setup...', '2006-01-31 17:52:37.000000', NULL, 1),
(2106262, 286727, 47117, '<td valign="top">I don''t get the concept of what looks like a tomatoe in a glass, but I am a sucker for water shots. I like the colors here, and the water, but I think it is a bit noisy or the wall is textured and blown out a bit. For advanced editing, it is a bit too bad you couldn''t fix that. But I will still give it an 8.</td>', 'I don''t get the concept of what looks like a tomatoe in a glass, but I am a sucker for water shots. I like the colors here, and the water, but I think it is a bit noisy or the wall is textured and blown out a bit. For advanced editing, it is a bit too bad you couldn''t fix that. But I will still give it an 8.', '2006-01-31 17:53:00.000000', NULL, 1),
(2106265, 287911, 47117, '<td valign="top">I like the odd composition here, and the silouette. A 9.</td>', 'I like the odd composition here, and the silouette. A 9.', '2006-01-31 17:53:48.000000', NULL, 1),
(2106266, 287185, 47704, '<td valign="top">Ok, I usually hate pet pics but MY GOD THIS DOG IS CUTE!!!!!</td>', 'Ok, I usually hate pet pics but MY GOD THIS DOG IS CUTE!!!!!', '2006-01-31 17:53:50.000000', NULL, 1),
(2106267, 286762, 47704, '<td valign="top">This better be a ribbon winner.  This is a GREAT picture.  Excellent job.  10</td>', 'This better be a ribbon winner.  This is a GREAT picture.  Excellent job.  10', '2006-01-31 17:54:17.000000', NULL, 1),
(2106268, 285450, 47117, '<td valign="top">LOL...Oh man, to catch this shot must have been ecstasy!  Never mind don''t move, they should be running their arses off! LOL...A 9.</td>', 'LOL...Oh man, to catch this shot must have been ecstasy!  Never mind don''t move, they should be running their arses off! LOL...A 9.', '2006-01-31 17:54:35.000000', NULL, 1),
(2106269, 286419, 35786, '<td valign="top">wow- It seems I rarely get to see good images of pets! Excellent lighting and sharp too. Even tho the cats not looking at the camera I think it''s better for it. Good work! 8</td>', 'wow- It seems I rarely get to see good images of pets! Excellent lighting and sharp too. Even tho the cats not looking at the camera I think it''s better for it. Good work! 8', '2006-01-31 17:54:39.000000', NULL, 1),
(2106271, 285795, 47117, '<td valign="top">Gosh, I had about a million and one seagul shots to enter, but thought it would be done. It has, by you, but done nicely. An 8.</td>', 'Gosh, I had about a million and one seagul shots to enter, but thought it would be done. It has, by you, but done nicely. An 8.', '2006-01-31 17:55:15.000000', NULL, 1),
(2106278, 286351, 47704, '<td valign="top">What an intersting picture.  Can''t wait until voting is over.  Please post and explanation of the subject.  8</td>', 'What an intersting picture.  Can''t wait until voting is over.  Please post and explanation of the subject.  8', '2006-01-31 17:56:37.000000', NULL, 1),
(2106279, 287848, 47117, '<td valign="top">I like the simplicity of this shot. I would guess you are the same one that did the spoon in the other challenge? LOL....An 8.</td>', 'I like the simplicity of this shot. I would guess you are the same one that did the spoon in the other challenge? LOL....An 8.', '2006-01-31 17:56:42.000000', NULL, 1),
(2106280, 285936, 35786, '<td valign="top">love it- great colors!</td>', 'love it- great colors!', '2006-01-31 17:56:52.000000', NULL, 1),
(2106285, 287620, 47117, '<td valign="top">Just when I thought a surfer would be a unique subject, I have seen quite a few. I love the colors in this and the reflection from the board. The contrast and saturation is spot on.  Nice job. An 8.</td>', 'Just when I thought a surfer would be a unique subject, I have seen quite a few. I love the colors in this and the reflection from the board. The contrast and saturation is spot on.  Nice job. An 8.', '2006-01-31 17:57:55.000000', NULL, 1),
(2106288, 287178, 35786, '<td valign="top">very cute kid! :0) the focus is a bit off tho as I''m sure you know</td>', 'very cute kid! :0) the focus is a bit off tho as I''m sure you know', '2006-01-31 17:58:25.000000', NULL, 1),
(2106290, 287440, 47117, '<td valign="top">I have tried three trips now to get a pelican. LOL...I have gone to the wrong beach three times too.  Next time it will be the right beach, but love this shot.  Love action shots of birds and wildlife, so an 8 from me.</td>', 'I have tried three trips now to get a pelican. LOL...I have gone to the wrong beach three times too.  Next time it will be the right beach, but love this shot.  Love action shots of birds and wildlife, so an 8 from me.', '2006-01-31 17:58:45.000000', NULL, 1),
