INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2113208, 287617, 52596, '<td valign="top">Nice composition. This one pulls my eyes around - great job.</td>', 'Nice composition. This one pulls my eyes around - great job.', '2006-02-02 00:21:08.000000', NULL, 1),
(2113219, 286036, 47294, '<td valign="top">Wow!!!  How did you capture this photo?  So stunning, good luck 10</td>', 'Wow!!!  How did you capture this photo?  So stunning, good luck 10', '2006-02-02 00:23:57.000000', NULL, 1),
(2113233, 286995, 52596, '<td valign="top">Great composition and your subject did her job well too.</td>', 'Great composition and your subject did her job well too.', '2006-02-02 00:27:34.000000', NULL, 1),
(2113247, 287150, 52596, '<td valign="top">Great shot and composition. I love the textures in this photo and the light on the horse''s chest. Nice work.</td>', 'Great shot and composition. I love the textures in this photo and the light on the horse''s chest. Nice work.', '2006-02-02 00:33:18.000000', NULL, 1),
(2113298, 287936, 52596, '<td valign="top">Excellent shot. Although I don''t see it on my cinema display, when viewing this photo on my Samsung SyncMaster, it looks as though parts of the background have been blacked out using a square brush, but the black used is darker than the original background of the image, revealing the technique.</td>', 'Excellent shot. Although I don''t see it on my cinema display, when viewing this photo on my Samsung SyncMaster, it looks as though parts of the background have been blacked out using a square brush, but the black used is darker than the original background of the image, revealing the technique.', '2006-02-02 00:49:05.000000', NULL, 1),
(2113306, 287126, 52596, '<td valign="top">Wonderful job with the lighting... kudos!</td>', 'Wonderful job with the lighting... kudos!', '2006-02-02 00:50:44.000000', NULL, 1),
(2113313, 287763, 52596, '<td valign="top">Great composition and I like your choice to gradient out the base of the photo.</td>', 'Great composition and I like your choice to gradient out the base of the photo.', '2006-02-02 00:51:50.000000', NULL, 1),
(2113320, 286022, 29474, '<td valign="top">Good marks for timing.</td>', 'Good marks for timing.', '2006-02-02 00:55:35.000000', NULL, 1),
(2113324, 287950, 52596, '<td valign="top">Great composition and I love the soft diffused glow and the sepia color instead of grey-scale - great choices!</td>', 'Great composition and I love the soft diffused glow and the sepia color instead of grey-scale - great choices!', '2006-02-02 00:57:28.000000', NULL, 1),
(2113329, 287745, 29269, '<td valign="top">Grain works well here with gloomy skies.</td>', 'Grain works well here with gloomy skies.', '2006-02-02 00:58:36.000000', NULL, 1),
(2113334, 287144, 52596, '<td valign="top">Nice job with the lights - interesting composition... I''m assuming you used a black gradient to hide something distracting there, leaving just the top of the tee pee? I like!</td>', 'Nice job with the lights - interesting composition... I''m assuming you used a black gradient to hide something distracting there, leaving just the top of the tee pee? I like!', '2006-02-02 00:59:51.000000', NULL, 1),
(2113337, 287994, 52596, '<td valign="top">I would have named this one "Right Off The Lot" cuz the reflection off the paint job is awesome. Nice work.</td>', 'I would have named this one "Right Off The Lot" cuz the reflection off the paint job is awesome. Nice work.', '2006-02-02 01:00:42.000000', NULL, 1),
(2113353, 287030, 52596, '<td valign="top">Oh very nice... Kudos on your masking on this one. Excellent choices for this shot.</td>', 'Oh very nice... Kudos on your masking on this one. Excellent choices for this shot.', '2006-02-02 01:04:11.000000', NULL, 1),
(2113355, 287993, 52596, '<td valign="top">You know what I like best about this shot? The brilliant white you''re getting off the cup and the fact that you did not go entirely grey-scale for the background. The putty tone was a great choice. Nice.</td>', 'You know what I like best about this shot? The brilliant white you''re getting off the cup and the fact that you did not go entirely grey-scale for the background. The putty tone was a great choice. Nice.', '2006-02-02 01:06:28.000000', NULL, 1),
(2113371, 286553, 52596, '<td valign="top">This is a great combination of detail and depth of field working well together. Excellent work!</td>', 'This is a great combination of detail and depth of field working well together. Excellent work!', '2006-02-02 01:11:53.000000', NULL, 1),
