(2117393, 287824, 21430, '<td valign="top">Well composed shot, but a little flat with the coloring. Perhaps a bit of bumping up the saturation in the yellow, a tad of red and a bit of the green channel could kick this up a notch.</td>', 'Well composed shot, but a little flat with the coloring. Perhaps a bit of bumping up the saturation in the yellow, a tad of red and a bit of the green channel could kick this up a notch.', '2006-02-03 08:22:53.000000', NULL, 1),
(2117394, 287926, 42638, '<td valign="top">Wonderful color and textures, I really like the glow of the sun through his hands and the shadows. Well done.</td>', 'Wonderful color and textures, I really like the glow of the sun through his hands and the shadows. Well done.', '2006-02-03 08:23:25.000000', NULL, 1),
(2117398, 287966, 21430, '<td valign="top">Great idea, the only issue is the lighting. The shadow from the plate distracts from the image. The best ways to over come this is to either bounce the light with a white surface or an additional light off to the right to diffuse the shadow more.</td>', 'Great idea, the only issue is the lighting. The shadow from the plate distracts from the image. The best ways to over come this is to either bounce the light with a white surface or an additional light off to the right to diffuse the shadow more.', '2006-02-03 08:24:56.000000', NULL, 1),
(2117407, 287126, 42638, '<td valign="top">Very nice, wish I could see the rest of the flower though, Love the use of space and greeen with shadows. Good colors.</td>', 'Very nice, wish I could see the rest of the flower though, Love the use of space and greeen with shadows. Good colors.', '2006-02-03 08:31:15.000000', NULL, 1),
