(2118083, 286354, 21816, '<td valign="top">Slightly orange looking. It could be my monitor but maybe you could of tried a slightly bigger DOF to help keep the hands and face nicely in focus becaue his eyes seem a little soft. The crop is fantastic!</td>', 'Slightly orange looking. It could be my monitor but maybe you could of tried a slightly bigger DOF to help keep the hands and face nicely in focus becaue his eyes seem a little soft. The crop is fantastic!', '2006-02-03 11:28:57.000000', NULL, 1),
(2118127, 287233, 52190, '<td valign="top">Very creative - nice composition!</td>', 'Very creative - nice composition!', '2006-02-03 11:44:30.000000', NULL, 1),
(2118138, 287769, 52190, '<td valign="top">I like this picture, but it looks a little underexposed on the cowboy. (I am no expert, so that is just my opinion.) Still, very nice picture!</td>', 'I like this picture, but it looks a little underexposed on the cowboy. (I am no expert, so that is just my opinion.) Still, very nice picture!', '2006-02-03 11:49:31.000000', NULL, 1),
(2118141, 287839, 52190, '<td valign="top">Nice reflections.</td>', 'Nice reflections.', '2006-02-03 11:50:09.000000', NULL, 1),
(2118148, 286359, 52190, '<td valign="top">Very creative and colorful!</td>', 'Very creative and colorful!', '2006-02-03 11:54:00.000000', NULL, 1),
(2118155, 287076, 52190, '<td valign="top">Beautiful composition - makes me want to be there!</td>', 'Beautiful composition - makes me want to be there!', '2006-02-03 11:57:42.000000', NULL, 1),
(2118160, 287926, 52190, '<td valign="top">Beautiful! Great detail!</td>', 'Beautiful! Great detail!', '2006-02-03 12:00:06.000000', NULL, 1),
(2118166, 287943, 52190, '<td valign="top">Yum!</td>', 'Yum!', '2006-02-03 12:02:53.000000', NULL, 1),
(2118236, 288007, 52190, '<td valign="top">Beautiful!! I love the viewers perspective.</td>', 'Beautiful!! I love the viewers perspective.', '2006-02-03 12:23:01.000000', NULL, 1),
(2118259, 287751, 31307, '<td valign="top">Funny and interesting shot.  It stands out in the thumbnails section.  Try this: instead of using the lasso tool to "pop" the horse''s ear in front of the border, use a mask and a soft edge brush to paint it in (using white on the mask layer).  By doin it that way, you get a slightly blurred edge like the one you have on the other untouched ear.  IT helps to get rid of that "photoshopped" look.</td>', 'Funny and interesting shot.  It stands out in the thumbnails section.  Try this: instead of using the lasso tool to "pop" the horse''s ear in front of the border, use a mask and a soft edge brush to paint it in (using white on the mask layer).  By doin it that way, you get a slightly blurred edge like the one you have on the other untouched ear.  IT helps to get rid of that "photoshopped" look.', '2006-02-03 12:29:25.000000', NULL, 1),
(2118402, 287126, 36808, '<td valign="top">Very elegant.</td>', 'Very elegant.', '2006-02-03 13:12:49.000000', NULL, 1),
(2118439, 286372, 36808, '<td valign="top">the linear aspects and textures are lovely!</td>', 'the linear aspects and textures are lovely!', '2006-02-03 13:27:19.000000', NULL, 1),
(2118501, 287554, 36808, '<td valign="top">jjbeguin-esque.  Engrossing.  I''ve come to it twice now just to absorb some more.  Good job!</td>', 'jjbeguin-esque.  Engrossing.  I''ve come to it twice now just to absorb some more.  Good job!', '2006-02-03 13:50:53.000000', NULL, 1),
(2118527, 287705, 36808, '<td valign="top">love the green...</td>', 'love the green...', '2006-02-03 13:58:57.000000', NULL, 1),
