(2118633, 288012, 50695, '<td valign="top">she doesn''t look innocent to me, but nice picture.</td>', 'she doesn''t look innocent to me, but nice picture.', '2006-02-03 14:21:11.000000', NULL, 1),
(2118658, 287825, 50695, '<td valign="top">I don''t normally like "special effects" shots, but this one shows great artistry. I think it''s my favorite photo of the challenge.</td>', 'I don''t normally like "special effects" shots, but this one shows great artistry. I think it''s my favorite photo of the challenge.', '2006-02-03 14:30:25.000000', NULL, 1),
