(2121402, 287150, 32997, '<td valign="top">that bit of red makes this shot..great composition..</td>', 'that bit of red makes this shot..great composition..', '2006-02-04 12:48:06.000000', NULL, 1),
(2121403, 287950, 40370, '<td valign="top">Terrific composition, I like this so much better than just another off-centered "head shot". Only thought to improve; black and white tones would have complimented the blues in the sweater better ... bumping up 9.</td>', 'Terrific composition, I like this so much better than just another off-centered "head shot". Only thought to improve; black and white tones would have complimented the blues in the sweater better ... bumping up 9.', '2006-02-04 12:48:08.000000', NULL, 1),
(2121410, 286406, 40370, '<td valign="top">Definitely the most interesting of the bird entries, love the focus and color, only thought is that the whole tail of the gray bird would have added more width to the image ... bumping up 8.</td>', 'Definitely the most interesting of the bird entries, love the focus and color, only thought is that the whole tail of the gray bird would have added more width to the image ... bumping up 8.', '2006-02-04 12:50:46.000000', NULL, 1),
