INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2123593, 288065, 42638, '<td valign="top">Wonderful color and details. Love the water and lines in this one. Well done!</td>', 'Wonderful color and details. Love the water and lines in this one. Well done!', '2006-02-05 07:53:41.000000', NULL, 1),
(2123594, 287752, 42638, '<td valign="top">Very nice, Love the texture on the ground and the leading lines to the off center sunset. I also like how you used the person there. Good color in the clouds.</td>', 'Very nice, Love the texture on the ground and the leading lines to the off center sunset. I also like how you used the person there. Good color in the clouds.', '2006-02-05 07:55:52.000000', NULL, 1),
(2123595, 287994, 42638, '<td valign="top">Wow, looks like a car brocure. Fantastic colors here and reflected on the car. The line on the car seems to intersect with the ridge of the wave, moving your eye through the picture. Well done!</td>', 'Wow, looks like a car brocure. Fantastic colors here and reflected on the car. The line on the car seems to intersect with the ridge of the wave, moving your eye through the picture. Well done!', '2006-02-05 07:56:53.000000', NULL, 1),
(2123596, 287979, 42638, '<td valign="top">Wow, very powerful here. Love the religious symbol, the lines on the wall behind really strengthen and further emphasize the suffering. There is almost a humble quietness about this. Nicely done.</td>', 'Wow, very powerful here. Love the religious symbol, the lines on the wall behind really strengthen and further emphasize the suffering. There is almost a humble quietness about this. Nicely done.', '2006-02-05 07:58:51.000000', NULL, 1),
(2123597, 287954, 42638, '<td valign="top">Wow, Interesting picture. Love all the lines from the poles and the color on the bird just pops right out. Excellent focus.</td>', 'Wow, Interesting picture. Love all the lines from the poles and the color on the bird just pops right out. Excellent focus.', '2006-02-05 07:59:27.000000', NULL, 1),
(2123598, 288072, 42638, '<td valign="top">Fantastic color here. Like how you used complimentary colors. The focus is right on. Lighting is a bit harsh on the top flower but not overpowering, it just takes from the softness. Excellent.</td>', 'Fantastic color here. Like how you used complimentary colors. The focus is right on. Lighting is a bit harsh on the top flower but not overpowering, it just takes from the softness. Excellent.', '2006-02-05 08:00:46.000000', NULL, 1),
(2123599, 287958, 42638, '<td valign="top">Very nice, Love the leading lines and color of the water. Wonderfull composition.</td>', 'Very nice, Love the leading lines and color of the water. Wonderfull composition.', '2006-02-05 08:00:51.000000', NULL, 1),
(2123600, 286862, 42638, '<td valign="top">Beautiful colors. Love the spread of feathers, wonderful translucent and detailed.</td>', 'Beautiful colors. Love the spread of feathers, wonderful translucent and detailed.', '2006-02-05 08:00:55.000000', NULL, 1),
(2123601, 287342, 42638, '<td valign="top">Fantastic use of space here. Good soft colors. The only suggestion I could offer is to maybe tilt these so its not so vertical. It just seem too ''in order'' or ''strict'' for the subject.</td>', 'Fantastic use of space here. Good soft colors. The only suggestion I could offer is to maybe tilt these so its not so vertical. It just seem too ''in order'' or ''strict'' for the subject.', '2006-02-05 08:02:43.000000', NULL, 1),
(2123602, 287253, 42638, '<td valign="top">Wonderful use of shadow.</td>', 'Wonderful use of shadow.', '2006-02-05 08:02:48.000000', NULL, 1),
(2123603, 287911, 42638, '<td valign="top">very nice silhoutte against the beautiful blue sky.</td>', 'very nice silhoutte against the beautiful blue sky.', '2006-02-05 08:04:10.000000', NULL, 1),
(2123604, 288049, 42638, '<td valign="top">Interesting picture. Took me a minute to see something missing. Good use of space and using the same color background as the dots really makes it work well.</td>', 'Interesting picture. Took me a minute to see something missing. Good use of space and using the same color background as the dots really makes it work well.', '2006-02-05 08:05:22.000000', NULL, 1),
(2123606, 287154, 42638, '<td valign="top">Very nice, Love the colors. It''s a bit harsh though, maybe contrasted too much. Good sharp focus.</td>', 'Very nice, Love the colors. It''s a bit harsh though, maybe contrasted too much. Good sharp focus.', '2006-02-05 08:06:17.000000', NULL, 1),
(2123607, 286368, 42638, '<td valign="top">Fantastic picture, Love the composition. The use of that shading technique really draws the eye toward your subject. Well done.</td>', 'Fantastic picture, Love the composition. The use of that shading technique really draws the eye toward your subject. Well done.', '2006-02-05 08:07:29.000000', NULL, 1),
(2123608, 285628, 42638, '<td valign="top">Wonderful colors.</td>', 'Wonderful colors.', '2006-02-05 08:07:36.000000', NULL, 1),
(2123609, 287753, 42638, '<td valign="top">Beautiful, almsot looks stormy. Love the texture in the water</td>', 'Beautiful, almsot looks stormy. Love the texture in the water', '2006-02-05 08:07:40.000000', NULL, 1),
(2123610, 288054, 42638, '<td valign="top">Ouch! That why I didn''t do judo, karate for me! Good capture, Wonderful timing.</td>', 'Ouch! That why I didn''t do judo, karate for me! Good capture, Wonderful timing.', '2006-02-05 08:09:24.000000', NULL, 1),
(2123611, 287845, 42638, '<td valign="top">Wonderful reflection. The top figure almost gets lost in the trees in the background. Good composition.</td>', 'Wonderful reflection. The top figure almost gets lost in the trees in the background. Good composition.', '2006-02-05 08:10:47.000000', NULL, 1),
(2123612, 286391, 42638, '<td valign="top">Beautiful picture. Love the white vase against the black, really sets the stage. Good sharp focus on the leaves while leaving the petals a bit softer. Nicely done!</td>', 'Beautiful picture. Love the white vase against the black, really sets the stage. Good sharp focus on the leaves while leaving the petals a bit softer. Nicely done!', '2006-02-05 08:12:04.000000', NULL, 1),
(2123616, 286705, 42638, '<td valign="top">Oh wow, talk about memories. My piano teacher was Mrs. Payne - really! Wonderful picture. Good composition. The lighting really adds to the ''memory'' feel of the picture.</td>', 'Oh wow, talk about memories. My piano teacher was Mrs. Payne - really! Wonderful picture. Good composition. The lighting really adds to the ''memory'' feel of the picture.', '2006-02-05 08:14:52.000000', NULL, 1),
(2123619, 288070, 42638, '<td valign="top">Wow, Wonderful macro. Excellent details. At leas I am assuming this is an eye, never see details like this before. Fascinating.</td>', 'Wow, Wonderful macro. Excellent details. At leas I am assuming this is an eye, never see details like this before. Fascinating.', '2006-02-05 08:16:05.000000', NULL, 1),
(2123621, 287755, 42638, '<td valign="top">wonderful subject. I like how the color is set add to the ''old'' look. Good natural frame on the left, gives the picture a nice completion.</td>', 'wonderful subject. I like how the color is set add to the ''old'' look. Good natural frame on the left, gives the picture a nice completion.', '2006-02-05 08:17:16.000000', NULL, 1),
(2123623, 287148, 42638, '<td valign="top">Fantastic pictue. Love the clarity in his eyes, really brings out his curious nature. Good capture with the biting, Most of my wood furniture had teeth marks from when mine were this age but never caught it on camera as evidence, lol.</td>', 'Fantastic pictue. Love the clarity in his eyes, really brings out his curious nature. Good capture with the biting, Most of my wood furniture had teeth marks from when mine were this age but never caught it on camera as evidence, lol.', '2006-02-05 08:19:00.000000', NULL, 1),
