(2127036, 287478, 15711, '<td valign="top">I figured this was you, but not til after I studied it and had commented.  Congrats on top 20~~~</td>', 'I figured this was you, but not til after I studied it and had commented.  Congrats on top 20~~~', '2006-02-06 14:25:22.000000', NULL, 0),
