INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2127046, 287176, 39850, '<td valign="top">I gave this a 6.  I thought the concept was good, colors also good.  Main ''detractors'' in this for me were; choice of base/background (minor) and the seemingly ''adult'' hand (again minor) - if it were a small/child''s hand, would have likely given it a little extra in my opinion.  If the frame were a little wider and subject even more off-centered, likely would have helped too - again ''in my opinion''.  Again, not good you received no comments during Challenge.</td>', 'I gave this a 6.  I thought the concept was good, colors also good.  Main ''detractors'' in this for me were; choice of base/background (minor) and the seemingly ''adult'' hand (again minor) - if it were a small/child''s hand, would have likely given it a little extra in my opinion.  If the frame were a little wider and subject even more off-centered, likely would have helped too - again ''in my opinion''.  Again, not good you received no comments during Challenge.', '2006-02-06 14:30:49.000000', NULL, 0),
(2127089, 287736, 14476, '<td valign="top">Interesting.  cpanaioti and I are on the same wavelength on this one.  (only I confess she was more generous in the scoring than I was.) But I do remember looking at it long and hard and giving it a lot of thought when it came up in the voting sequence.</td>', 'Interesting.  cpanaioti and I are on the same wavelength on this one.  (only I confess she was more generous in the scoring than I was.) But I do remember looking at it long and hard and giving it a lot of thought when it came up in the voting sequence.', '2006-02-06 14:45:40.000000', NULL, 0),
(2127126, 285901, 37961, '<td valign="top">Nice color palette. Really pretty pic.</td>', 'Nice color palette. Really pretty pic.', '2006-02-06 14:57:14.000000', NULL, 0),
(2127146, 287515, 16790, '<td valign="top">Awesome exposure.  I''d love to see a little grain in this... but I''m sure I''m in the minority.  Great job on that tonal range.  Judging by your portfolio, you''re very strong with b&amp;w, and that makes me happy.  Congrats on the ribbon!</td>', 'Awesome exposure.  I''d love to see a little grain in this... but I''m sure I''m in the minority.  Great job on that tonal range.  Judging by your portfolio, you''re very strong with b&w, and that makes me happy.  Congrats on the ribbon!', '2006-02-06 15:03:34.000000', NULL, 0),
(2127162, 287108, 39850, '<td valign="top">I gave this an 8.  And added it to my Favorites as you can see.  Very nice scene - looks like a painting.  A more finely tuned crop was my main ''criticism''.  I''m sure this ''wall sized'' would make a very good print.</td>', 'I gave this an 8.  And added it to my Favorites as you can see.  Very nice scene - looks like a painting.  A more finely tuned crop was my main ''criticism''.  I''m sure this ''wall sized'' would make a very good print.', '2006-02-06 15:10:41.000000', NULL, 0),
(2127166, 287975, 39850, '<td valign="top">I gave this an 8.  Really liked the subject, placement, texture and colors.  The cropping upper right adjusted and more detail, especially in the ''blades'' was the main ''criticism'' I had.</td>', 'I gave this an 8.  Really liked the subject, placement, texture and colors.  The cropping upper right adjusted and more detail, especially in the ''blades'' was the main ''criticism'' I had.', '2006-02-06 15:12:32.000000', NULL, 0),
(2127169, 287644, 39850, '<td valign="top">Gave this an 8.  Worked well.  Even sharper would have made it even better, but difficult.</td>', 'Gave this an 8.  Worked well.  Even sharper would have made it even better, but difficult.', '2006-02-06 15:13:55.000000', NULL, 0),
(2127171, 286406, 39850, '<td valign="top">Gave this an 8.  Liked the capture, angle/perspective and composition.  Just a fraction sharper on the sparrow(?) would have made it even better in my opinion.</td>', 'Gave this an 8.  Liked the capture, angle/perspective and composition.  Just a fraction sharper on the sparrow(?) would have made it even better in my opinion.', '2006-02-06 15:15:18.000000', NULL, 0),
(2127175, 287542, 39850, '<td valign="top">I gave this an 8, really liked it.  The main ''criticism'' I had was that I would liked to have seen the barb even ''sharper'', focal wise and ''feel'' wise.</td>', 'I gave this an 8, really liked it.  The main ''criticism'' I had was that I would liked to have seen the barb even ''sharper'', focal wise and ''feel'' wise.', '2006-02-06 15:17:05.000000', NULL, 0),
(2127180, 284922, 41746, '<td valign="top">This is what good photography is all about, seeing things and capturing them. I can´t imagine why this amazing photo was not recognised for it´s quality, not only is this one of the best examples of off-centered subject but humorous as well. Fantastic!<br/></td>', 'This is what good photography is all about, seeing things and capturing them. I can´t imagine why this amazing photo was not recognised for it´s quality, not only is this one of the best examples of off-centered subject but humorous as well. Fantastic!', '2006-02-06 15:18:18.000000', NULL, 0),
(2127182, 287067, 39850, '<td valign="top">I gave this an 8.  Good capture, the off-centering worked well in my opinion.  Wasn''t sure if it needed a slight nudge rotation or not.  Even sharper, albeit difficult, would have made this even better in my opinion.</td>', 'I gave this an 8.  Good capture, the off-centering worked well in my opinion.  Wasn''t sure if it needed a slight nudge rotation or not.  Even sharper, albeit difficult, would have made this even better in my opinion.', '2006-02-06 15:18:46.000000', NULL, 0),
