(2127188, 285450, 39850, '<td valign="top">Gave this an 8, excellent opportunity capture.  Really liked the three subjects here; children, dolphin and birds - which all appear to be in good focus.</td>', 'Gave this an 8, excellent opportunity capture.  Really liked the three subjects here; children, dolphin and birds - which all appear to be in good focus.', '2006-02-06 15:20:50.000000', NULL, 0),
(2127196, 288001, 39850, '<td valign="top">Gave this a 6 - liked the concept.  Couldn''t tell during voting what this was, but hazarded a guess it was a rabbit - way off I see now from your comments.  Not sure that many took the time to see the ''landscape''.  It was mainly the blown areas and OOF nose at the fore that dominated the shot most in my opinion and why I didn''t vote it higher.</td>', 'Gave this a 6 - liked the concept.  Couldn''t tell during voting what this was, but hazarded a guess it was a rabbit - way off I see now from your comments.  Not sure that many took the time to see the ''landscape''.  It was mainly the blown areas and OOF nose at the fore that dominated the shot most in my opinion and why I didn''t vote it higher.', '2006-02-06 15:23:40.000000', NULL, 0),
(2127198, 287313, 39007, '<td valign="top">Fantastic photo, love the title too!</td>', 'Fantastic photo, love the title too!', '2006-02-06 15:24:23.000000', NULL, 0),
